/// Task 1:
/// Given a non-empty collection of dtypes, return a dtype that appears
/// in the collection and whose precedence is at least as large as every dtype in the collection.
fn find_max_precedence_type(types: Vec<DType>) -> DType {
    // Since types is non-empty, safe to start with first element as max candidate.
    let mut max_dtype = types[0];
    for &dt in &types[1..] {
        if dt.precedence > max_dtype.precedence {
            max_dtype = dt;
        }
    }
    max_dtype
}

/// Task 2:
/// Given two collections of dtypes (arrays and scalars), return the common dtype according to:
/// - If only array_types provided (scalar_types empty), return max from array_types.
/// - If only scalar_types provided (array_types empty), return max from scalar_types.
/// - If both non-empty:
///     * Compute max from each collection.
///     * If their kinds match, return max from array_types.
///     * Else, return max from scalar_types.
///
/// Returns Option<DType> since both collections can be empty, though problem states at least
/// one collection non-empty (but be safe).
fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    let has_array = !array_types.is_empty();
    let has_scalar = !scalar_types.is_empty();

    match (has_array, has_scalar) {
        (false, false) => None, // no input types at all
        (true, false) => Some(find_max_precedence_type(array_types)),
        (false, true) => Some(find_max_precedence_type(scalar_types)),
        (true, true) => {
            let max_array = find_max_precedence_type(array_types);
            let max_scalar = find_max_precedence_type(scalar_types);
            if max_array.kind == max_scalar.kind {
                Some(max_array)
            } else {
                Some(max_scalar)
            }
        }
    }
}

